  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tenant_key`(`tenant_id` ASC, `config_key` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '闂ㄥ簵閰嶇疆' ROW_FORMAT = DYNAMIC;

