CREATE TABLE `store_daily_summary`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '涓婚敭',
  `tenant_id` bigint NOT NULL COMMENT '闂ㄥ簵ID',
  `summary_date` date NOT NULL COMMENT '缁熻?鏃ユ湡',
  `total_orders` int NOT NULL DEFAULT 0 COMMENT '璁㈠崟鎬绘暟',
  `completed_orders` int NOT NULL DEFAULT 0 COMMENT '宸插畬鎴愯?鍗曟暟',
  `cancelled_orders` int NOT NULL DEFAULT 0 COMMENT '鍙栨秷璁㈠崟鏁',
  `total_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '璁㈠崟鎬婚?',
  `actual_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '瀹炴敹閲戦?',
  `new_users` int NOT NULL DEFAULT 0 COMMENT '鏂板?鐢ㄦ埛鏁',
  `avg_order_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '骞冲潎璁㈠崟閲戦?',
  `top_dish_json` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '鐑?攢鑿滃搧TOP10 JSON',
  `create_time` datetime NOT NULL COMMENT '鍒涘缓鏃堕棿',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tenant_date`(`tenant_id` ASC, `summary_date` ASC) USING BTREE,
  INDEX `idx_date`(`summary_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '闂ㄥ簵姣忔棩缁忚惀姹囨?' ROW_FORMAT = DYNAMIC;

