  INDEX `idx_tenant`(`tenant_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '闂ㄥ簵鍛樺伐鏉冮檺鍏宠仈' ROW_FORMAT = DYNAMIC;

