DROP TABLE IF EXISTS `store_info`;
CREATE TABLE `store_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '涓婚敭',
  `tenant_id` bigint NOT NULL COMMENT '鎵?睘绉熸埛/闂ㄥ簵ID',
  `store_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '闂ㄥ簵缂栫爜锛屽?锛欱J001銆丼H001',
  `store_type` tinyint NOT NULL DEFAULT 1 COMMENT '闂ㄥ簵绫诲瀷 1:鐩磋惀鎬诲簵 2:鐩磋惀鍒嗗簵 3:鍔犵洘搴',
  `parent_tenant_id` bigint NULL DEFAULT NULL COMMENT '涓婄骇鎬诲簵tenantId锛孨ULL琛ㄧず鎬诲簵鑷?韩',
  `business_hours` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '钀ヤ笟鏃堕棿锛屽?锛?9:00-22:00',
  `delivery_radius` int NOT NULL DEFAULT 3000 COMMENT '閰嶉?鍗婂緞(绫?',
  `min_delivery_amount` decimal(10, 2) NOT NULL DEFAULT 20.00 COMMENT '鏈?綆璧烽?閲戦?',
  `delivery_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '閰嶉?璐',
  `is_delivery_enabled` tinyint NOT NULL DEFAULT 1 COMMENT '鏄?惁鏀?寔澶栧崠 0:鍚?1:鏄',
  `is_dine_in_enabled` tinyint NOT NULL DEFAULT 1 COMMENT '鏄?惁鏀?寔鍫傞? 0:鍚?1:鏄',
  `contact_person` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '闂ㄥ簵鑱旂郴浜',
  `contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '闂ㄥ簵鑱旂郴鐢佃瘽',
  `longitude` decimal(10, 7) NULL DEFAULT NULL COMMENT '缁忓害',
  `latitude` decimal(10, 7) NULL DEFAULT NULL COMMENT '绾?害',
  `create_time` datetime NOT NULL COMMENT '鍒涘缓鏃堕棿',
  `update_time` datetime NOT NULL COMMENT '鏇存柊鏃堕棿',
  `create_user` bigint NOT NULL COMMENT '鍒涘缓浜',
  `update_user` bigint NOT NULL COMMENT '淇?敼浜',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tenant`(`tenant_id` ASC) USING BTREE,
  INDEX `idx_parent`(`parent_tenant_id` ASC) USING BTREE,
  INDEX `idx_code`(`store_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '闂ㄥ簵鎵╁睍淇℃伅' ROW_FORMAT = DYNAMIC;

