-- ----------------------------
-- Table structure for store_sync_log
-- ----------------------------
DROP TABLE IF EXISTS `store_sync_log`;
CREATE TABLE `store_sync_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '涓婚敭',
  `source_tenant_id` bigint NOT NULL COMMENT '鏉ユ簮闂ㄥ簵ID(閫氬父鏄??閮?',
  `target_tenant_id` bigint NOT NULL COMMENT '鐩?爣闂ㄥ簵ID',
  `sync_type` tinyint NOT NULL COMMENT '鍚屾?绫诲瀷 1:鑿滃搧鍚屾? 2:鍒嗙被鍚屾? 3:濂楅?鍚屾? 4:閰嶇疆鍚屾? 5:浼樻儬鍒稿悓姝',
  `sync_mode` tinyint NOT NULL DEFAULT 1 COMMENT '鍚屾?妯″紡 1:鍏ㄩ噺鍚屾? 2:澧為噺鍚屾? 3:閫夋嫨鎬у悓姝',
  `sync_status` tinyint NOT NULL DEFAULT 0 COMMENT '鍚屾?鐘舵? 0:杩涜?涓?1:鎴愬姛 2:澶辫触 3:閮ㄥ垎鎴愬姛',
  `sync_count` int NOT NULL DEFAULT 0 COMMENT '鍚屾?鏁伴噺',
  `fail_count` int NOT NULL DEFAULT 0 COMMENT '澶辫触鏁伴噺',
  `error_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '閿欒?璇︽儏',
  `operator_id` bigint NOT NULL COMMENT '鎿嶄綔浜篒D',
  `start_time` datetime NOT NULL COMMENT '寮??鏃堕棿',
  `end_time` datetime NULL DEFAULT NULL COMMENT '缁撴潫鏃堕棿',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_source`(`source_tenant_id` ASC) USING BTREE,
  INDEX `idx_target`(`target_tenant_id` ASC) USING BTREE,
  INDEX `idx_status`(`sync_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '闂ㄥ簵鍚屾?鏃ュ織' ROW_FORMAT = DYNAMIC;

