  `update_user` bigint NULL DEFAULT NULL COMMENT '修改人',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2075157889845473283 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin COMMENT = '租户' ROW_FORMAT = DYNAMIC;

