-- ----------------------------
-- Table structure for user_preference_tag
-- ----------------------------
DROP TABLE IF EXISTS `user_preference_tag`;
CREATE TABLE `user_preference_tag`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '涓婚敭',
  `user_id` bigint NOT NULL COMMENT '鐢ㄦ埛ID',
  `tenant_id` bigint NULL DEFAULT NULL COMMENT '绉熸埛ID',
  `tag_type` tinyint NOT NULL COMMENT '鏍囩?绫诲瀷 1:鍙ｅ懗鍋忓ソ 2:鍝佺被鍋忓ソ 3:浠锋牸鍋忓ソ 4:鏃舵?鍋忓ソ',
  `tag_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '鏍囩?鍚嶇О锛屽?锛氳荆鍛炽?宸濊彍銆?0-30鍏冦?鍗堥?鏃舵?',
  `tag_value` decimal(5, 2) NOT NULL DEFAULT 1.00 COMMENT '鍋忓ソ鏉冮噸 0.00~1.00锛岃秺楂樿秺鍋忓ソ',
  `source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'ORDER' COMMENT '鏁版嵁鏉ユ簮 ORDER:璁㈠崟鍒嗘瀽 BROWSE:娴忚?鍒嗘瀽 MANUAL:鎵嬪姩鏍囨敞',
  `create_time` datetime NOT NULL COMMENT '鍒涘缓鏃堕棿',
  `update_time` datetime NOT NULL COMMENT '鏇存柊鏃堕棿',
  `create_user` bigint NOT NULL COMMENT '鍒涘缓浜',
  `update_user` bigint NOT NULL COMMENT '淇?敼浜',
  PRIMARY KEY (`id`) USING BTREE,
